import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# packet.ActorEvent{EntityRuntimeID: 300, EventType: packet.ActorEventHurt, EventData: -3,
#   FireAtPosition: protocol.Option(mgl32.Vec3{1, 2, 3})}
GOLDEN = bytes.fromhex("ac020205010000803f0000004000004040")

# generated by gophertunnel b8bd735:
# packet.ActorEvent{EntityRuntimeID: 7, EventType: packet.ActorEventHurtWithoutReceivingDamage, EventData: 0}
WITHOUT_POSITION = bytes.fromhex("07510000")

# generated by gophertunnel b8bd735:
# packet.ActorEvent{EntityRuntimeID: 1 << 32, EventType: packet.ActorEventAddPlayerLevels, EventData: -1}
WIDE_RUNTIME_ID = bytes.fromhex("8080808010220100")

GOLDENS = [
    pytest.param(
        v2225.ActorEventPacket(
            runtime_id=300,
            event_id=v2225.ActorEvent.HURT,
            data=-3,
            fire_at_position=v2225.Vec3(x=1.0, y=2.0, z=3.0),
        ),
        GOLDEN,
        id="with-position",
    ),
    pytest.param(
        v2225.ActorEventPacket(
            runtime_id=7,
            event_id=v2225.ActorEvent.HURT_WITHOUT_RECEIVING_DAMAGE,
            data=0,
            fire_at_position=None,
        ),
        WITHOUT_POSITION,
        id="without-position",
    ),
    pytest.param(
        v2225.ActorEventPacket(
            runtime_id=1 << 32,
            event_id=v2225.ActorEvent.DEPRECATED_ADD_PLAYER_LEVELS,
            data=-1,
        ),
        WIDE_RUNTIME_ID,
        id="wide-runtime-id",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225])
def test_actor_event_is_packet_27(version):
    assert version.packets[27] is version.ActorEventPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_actor_event_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_actor_event_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
